// bundle.js: generates bundle_data.luau — every game module's source as a
// Luau table of long-bracket strings, so the test harness can load the real
// modules without needing io.open (the luau CLI strips the io library).
// Run: node tests/bundle.js   (from the aura-farm project root)

const fs = require("fs");
const path = require("path");

const projectRoot = path.resolve(__dirname, "..");
const srcRoot = path.join(projectRoot, "src");

function collect(dir, prefix, out) {
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, entry.name);
		const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
		if (entry.isDirectory()) {
			collect(full, rel, out);
		} else if (entry.name.endsWith(".lua") || entry.name.endsWith(".luau")) {
			out[rel] = fs.readFileSync(full, "utf8");
		}
	}
}

const modules = {};
collect(srcRoot, "src", modules);

function luauString(s) {
	// Long brackets: pick a level with no closing sequence present.
	let level = 0;
	while (s.includes("]" + "=".repeat(level) + "]")) level += 1;
	const eq = "=".repeat(level);
	return `[${eq}[\n${s}]${eq}]`;
}

let out = "-- AUTO-GENERATED by tests/bundle.js — do not edit.\nreturn {\n";
for (const [key, source] of Object.entries(modules)) {
	out += `\t["${key}"] = ${luauString(source)},\n`;
}
out += "}\n";

const dest = path.join(__dirname, "bundle_data.luau");
fs.writeFileSync(dest, out);
console.log(`bundled ${Object.keys(modules).length} modules -> ${dest}`);
